from __future__ import annotations
from math import gcd
from typing import List, Tuple

def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def lucas(n: int) -> int:
    a, b = 2, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def rank_of_apparition(m: int) -> int:
    if m <= 0:
        raise ValueError('m > 0 required')
    a, b, k = 0, 1, 0
    while True:
        k += 1
        a, b = b % m, (a + b) % m
        if a == 0:
            return k

def two_adic_split(x: int) -> Tuple[int, int]:
    v = 0
    while x % 2 == 0:
        x //= 2
        v += 1
    return v, x

def criterion(p: int, n: int) -> bool:
    r = rank_of_apparition(p)
    return (2 * n) % r == 0 and n % r != 0

def two_adic_criterion(p: int, n: int) -> bool:
    a, s = two_adic_split(rank_of_apparition(p))
    b, t = two_adic_split(n)
    return a >= 1 and b == a - 1 and t % s == 0

def actual(p: int, n: int) -> bool:
    return lucas(n) % p == 0

def apparition_set(p: int, max_n: int) -> List[int]:
    return [n for n in range(1, max_n + 1) if actual(p, n)]

if __name__ == '__main__':
    print('Doubling bridge   :', all(fib(2*n) == fib(n)*lucas(n) for n in range(26)))
    print('Quadratic identity:', all(lucas(n)**2 - 5*fib(n)**2 == 4*(-1)**n for n in range(26)))
    print('Near-coprimality  :', all(2 % gcd(lucas(n), fib(n)) == 0 for n in range(1, 41)))
    for p in [3, 7, 11, 13, 17, 19, 23]:
        r = rank_of_apparition(p)
        ok = all(criterion(p, n) == actual(p, n) for n in range(1, 81))
        ok2 = all(two_adic_criterion(p, n) == actual(p, n) for n in range(1, 81))
        print(f'p={p:2d} r={r:2d} criterion={ok} two_adic={ok2} set={apparition_set(p, 60)}')

from __future__ import annotations

def rank_of_apparition(m: int) -> int:
    a, b, k = 0, 1, 0
    while True:
        k += 1
        a, b = b % m, (a + b) % m
        if a == 0:
            return k

def lucas_mod(n: int, p: int) -> int:
    a, b = 2 % p, 1 % p
    for _ in range(n):
        a, b = b, (a + b) % p
    return a

def oracle(p: int, n: int, r: int) -> bool:
    return (2 * n) % r == 0 and n % r != 0

if __name__ == '__main__':
    for p in [7, 11, 19, 23, 31, 47]:
        r = rank_of_apparition(p)
        agree = all(oracle(p, n, r) == (lucas_mod(n, p) == 0) for n in range(1, 500))
        sample = next((n for n in range(1, 10**6) if oracle(p, n, r)), None)
        print(f'p={p:3d} rank={r:3d} oracle matches direct (n<500): {agree}; first hit n={sample}')

